      b.addEventListener('click', function(){ setMode(b.dataset.mode); });
    });

    /* ---- Theme toggle: Day / Night ---- */
    var root = document.body;
    var ttBtn = document.getElementById('themeToggle');
    var ttIco = document.getElementById('ttIco');
    var ttLbl = document.getElementById('ttLbl');

    function applyTheme(t){
      var night = t === 'night';
      root.setAttribute('data-theme', night ? 'night' : 'day');
      ttBtn.setAttribute('aria-pressed', night ? 'true' : 'false');
      ttBtn.setAttribute('aria-label', night ? 'Switch to Day Mode' : 'Switch to Night Mode');
      ttIco.textContent = night ? '☀️' : '🌙';
      ttLbl.textContent = night ? 'Day Mode' : 'Night Mode';
      try { localStorage.setItem('sky-theme', night ? 'night' : 'day'); } catch (e) {}
    }
    function toggleTheme(){
      applyTheme(root.getAttribute('data-theme') === 'night' ? 'day' : 'night');
    }
    ttBtn.addEventListener('click', toggleTheme);

    /* ---- Star field generation (embedded, no external assets) ---- */
    var fields = Array.prototype.slice.call(document.querySelectorAll('.stars i'));
    function buildStars(){
      var w = Math.max(window.innerWidth, 1600);
      var h = Math.max(window.innerHeight, 1200);
      fields.forEach(function(el){
        var n = el.className.indexOf('b') > -1 ? 70 : 120;
        var sh = [];
        for (var i = 0; i < n; i++){
          var x = (Math.random() * w) | 0;
          var y = (Math.random() * h) | 0;
          var a = (0.4 + Math.random() * 0.6).toFixed(2);
          sh.push(x + 'px ' + y + 'px 0 0 rgba(255,255,255,' + a + ')');
        }
        el.style.boxShadow = sh.join(',');
      });
    }
    buildStars();
    var rt; window.addEventListener('resize', function(){
      clearTimeout(rt); rt = setTimeout(buildStars, 250);
    });

    /* ---- Keyboard shortcuts ---- */
    document.addEventListener('keydown', function(e){
      if(e.target && /input|textarea/i.test(e.target.tagName)) return;
      if(e.key === '1') setMode('both');
      if(e.key === '2') setMode('en');
      if(e.key === '3') setMode('zh');
      if(e.key === 't' || e.key === 'T') toggleTheme();
    });

    /* ---- Initial theme (saved preference or system) ---- */
    var saved = null;
    try { saved = localStorage.getItem('sky-theme'); } catch (e) {}
    if(!saved && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches){
      saved = 'night';
    }
    applyTheme(saved === 'night' ? 'night' : 'day');
  })();", "oldText": "  (function(){
