{"content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>طبقات الأرض · القشرة والوشاح واللب</title>
<style>
  :root{
    --bg:#0b1020;
    --bg-2:#0f1830;
    --panel:#141f3a;
    --panel-2:#182646;
    --line:#28375c;
    --ink:#eaf0ff;
    --ink-soft:#a9b8dc;
    --brand:#ffb457;
    --brand-2:#ff6b6b;

    --crust:#7a5a3a;
    --crust-2:#a8794c;
    --mantle:#d9662b;
    --mantle-2:#f08a3c;
    --outer:#ff8a1f;
    --outer-2:#ffc24b;
    --inner:#fff2b0;
    --inner-2:#ffe27a;

    --shadow:0 18px 50px rgba(0,0,0,.55);
    --radius:18px;
    --maxw:1080px;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    margin:0;
    font-family:"Noto Naskh Arabic","Segoe UI",Tahoma,"Geeza Pro","Al Bayan",
                "Times New Roman",system-ui,-apple-system,sans-serif;
    color:var(--ink);
    line-height:1.9;
    background:
      radial-gradient(1100px 520px at 90% -8%, #1b2a52 0%, transparent 60%),
      radial-gradient(900px 460px at 5% 0%, #16264a 0%, transparent 55%),
      linear-gradient(180deg,var(--bg) 0%, var(--bg-2) 100%);
    background-attachment:fixed;
    -webkit-font-smoothing:antialiased;
    min-height:100vh;
  }
  .wrap{max-width:var(--maxw);margin:0 auto;padding:32px 20px 80px}

  /* Header */
  header.hero{
    text-align:center;
    padding:48px 22px 34px;
    border-radius:26px;
    background:linear-gradient(180deg,#1a2c5a 0%,#122murky 100%),
               radial-gradient(600px 300px at 50% -20%, #24386e 0%, transparent 70%);
    background-color:#152447;
    box-shadow:var(--shadow);
    border:1px solid var(--line);
    position:relative;overflow:hidden;
  }
  header.hero h1{
    margin:0;
    font-size:clamp(1.8rem,4.5vw,3rem);
    letter-spacing:.2px;
    background:linear-gradient(90deg,#ffd08a,#ff8f6b,#ffcf6b);
    -webkit-background-clip:text;background-clip:text;color:transparent;
  }
  header.hero .sub{color:var(--ink-soft);margin-top:10px;font-size:clamp(.95rem,2.2vw,1.15rem)}
  header.hero .tag{
    display:inline-block;margin-top:16px;font-size:.82rem;color:var(--ink);
    padding:6px 16px;border-radius:999px;border:1px solid var(--line);background:#0f1c39;
  }
  .globe{
    width:64px;height:64px;border-radius:50%;margin:0 auto 8px;
    background:radial-gradient(circle at 35% 30%, #7fd3ff, #1c74c4 55%, #0a3a72 100%);
    box-shadow:0 0 34px 6px rgba(60,150,255,.4), inset -6px -8px 14px rgba(0,0,0,.45);
    position:relative;
  }
  .globe::before{content:"";position:absolute;inset:0;border-radius:50%;
    background:
      radial-gradient(closest-side at 30% 60%, rgba(80,190,120,.9) 0 60%, transparent 61%),
      radial-gradient(closest-side at 68% 38%, rgba(80,190,120,.85) 0 55%, transparent 56%),
      radial-gradient(closest-side at 55% 72%, rgba(90,200,130,.7) 0 45%, transparent 46%);
  }

  h2.section{
    font-size:clamp(1.25rem,3vw,1.8rem);margin:46px 4px 18px;color:#ffd9a0;
    display:flex;align-items:center;gap:10px;
  }
  h2.section .dot{width:10px;height:10px;border-radius:50%;background:var(--brand);box-shadow:0 0 12px var(--brand)}

  /* Diagram + interactive */
  .stage{
    display:grid;grid-template-columns:320px 1fr;gap:30px;align-items:center;
    background:linear-gradient(180deg,var(--panel),var(--panel-2));
    border:1px solid var(--line);border-radius:var(--radius);
    padding:28px;box-shadow:var(--shadow);
  }
  @media (max-width:820px){ .stage{grid-template-columns:1fr;justify-items:center;text-align:center} }

  .earth-box{display:flex;flex-direction:column;align-items:center;gap:18px}
  .earth{
    --D:min(60vw,320px);
    width:var(--D);height:var(--D);border-radius:50%;position:relative;
    box-shadow:var(--shadow), 0 0 0 6px rgba(255,255,255,.03);
    background:radial-gradient(circle at 50% 50%, #0000 0 0), var(--crust);
    isolation:isolate;
  }
  .earth .ring{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
    border-radius:50%;transition:box-shadow .35s ease, transform .35s ease, filter .35s ease;cursor:pointer}
  .earth .ring:focus-visible{outline:3px solid #fff;outline-offset:2px}
  .earth .crust{width:100%;height:100%;background:
      repeating-linear-gradient(45deg, rgba(0,0,0,.06) 0 6px, transparent 6px 12px),
      radial-gradient(circle at 38% 32%, var(--crust-2), var(--crust));}
  .earth .mantle{width:92%;height:92%;background:radial-gradient(circle at 40% 34%, var(--mantle-2), var(--mantle) 70%, #b5521f);}
  .earth .outer{width:60%;height:60%;background:radial-gradient(circle at 42% 36%, var(--outer-2), var(--outer) 72%, #d9741a);}
  .earth .inner{width:26%;height:26%;background:radial-gradient(circle at 45% 40%, #fffef2, var(--inner) 60%, var(--inner-2));
    box-shadow:0 0 30px 6px rgba(255,236,150,.6);}
  /* sphere shading overlay */
  .earth::after{content:"";position:absolute;inset:0;border-radius:50%;pointer-events:none;z-index:5;
    background:radial-gradient(circle at 32% 26%, rgba(255,255,255,.35), rgba(255,255,255,0) 45%),
               radial-gradient(circle at 70% 78%, rgba(0,0,0,.35), rgba(0,0,0,0) 55%);}
  /* highlight when selected */
  .earth[data-active="crust"] .crust,
  .earth[data-active="mantle"] .mantle,
  .earth[data-active="outer"] .outer,
  .earth[data-active="inner"] .inner{
    filter:brightness(1.18) saturate(1.1);
    box-shadow:0 0 0 3px #fff, 0 0 26px rgba(255,255,255,.55);
    transform:translate(-50%,-50%) scale(1.015);
  }

  /* Legend / chips */
  .legend{display:grid;gap:8px;width:100%;max-width:320px}
  .chip{
    display:flex;align-items:center;gap:10px;width:100%;text-align:start;
    font:inherit;color:var(--ink);cursor:pointer;
    background:#0f1c39;border:1px solid var(--line);border-radius:12px;padding:10px 12px;
    transition:background .2s ease,border-color .2s ease,transform .12s ease;
  }
  .chip:hover{transform:translateX(-3px);border-color:var(--brand)}
  .chip[aria-pressed="true"]{background:#1b2c55;border-color:var(--brand)}
  .chip .sw{width:16px;height:16px;border-radius:5px;flex:0 0 auto;box-shadow:inset 0 0 0 1px rgba(255,255,255,.25)}
  .chip small{color:var(--ink-soft);font-size:.78rem}
  .sw.crust{background:var(--crust-2)} .sw.mantle{background:var(--mantle-2)}
  .sw.outer{background:var(--outer-2)} .sw.inner{background:var(--inner)}

  /* Info panel */
  .info{background:#0f1c39;border:1px solid var(--line);border-radius:14px;padding:20px 22px;min-height:240px}
  .info h3{margin:0 0 6px;font-size:1.35rem;color:#ffd9a0}
  .info .lead{color:var(--ink-soft);margin:0 0 14px}
  .facts{list-style:none;padding:0;margin:0;display:grid;gap:10px}
  .facts li{display:flex;gap:10px;align-items:baseline}
  .facts .k{color:var(--brand);font-weight:700;min-width:90px}
  .bar{height:8px;border-radius:6px;background:#22335a;overflow:hidden;margin-top:4px}
  .bar > i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,var(--brand),var(--brand-2));transition:width .5s ease}

  /* Layer cards */
  .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px}
  .card{background:linear-gradient(180deg,var(--panel),var(--panel-2));
    border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow);
    border-top:5px solid var(--c,#888);transition:transform .2s ease,border-color .2s ease}
  .card:hover{transform:translateY(-4px)}
  .card h3{margin:0 0 4px;font-size:1.25rem}
  .card .depth{color:var(--ink-soft);font-size:.85rem;margin:0 0 12px}
  .card dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:6px 12px;font-size:.92rem}
  .card dt{color:var(--c,#ccc);font-weight:700}
  .card dd{margin:0;color:var(--ink)}
  .card.crust{--c:var(--crust-2)} .card.mantle{--c:var(--mantle-2)}
  .card.outer{--c:var(--outer-2)} .card.inner{--c:var(--inner)}

  /* Scale / depth strip */
  .scale{display:flex;flex-direction:column;border-radius:14px;overflow:hidden;border:1px solid var(--line);box-shadow:var(--shadow)}
  .scale .band{padding:16px 18px;display:flex;justify-content:space-between;align-items:center;gap:14px;color:#1a1206;font-weight:700}
  .scale .band .t{font-weight:400;font-size:.86rem;opacity:.85}
  .band.crust{background:linear-gradient(90deg,var(--crust-2),var(--crust))}
  .band.mantle{background:linear-gradient(90deg,var(--mantle-2),var(--mantle));color:#fff}
  .band.outer{background:linear-gradient(90deg,var(--outer-2),var(--outer));color:#3a1c00}
  .band.inner{background:linear-gradient(90deg,#fffef2,var(--inner-2));color:#3a2c00}

  /* Facts */
  .facts-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
  .fact{background:#0f1c39;border:1px solid var(--line);border-radius:14px;padding:18px}
  .fact .big{font-size:1.7rem;font-weight:800;color:#ffd9a0;line-height:1.2}
  .fact .lbl{color:var(--ink-soft);font-size:.9rem;margin-top:4px}

  footer{margin-top:50px;text-align:center;color:var(--ink-soft);font-size:.85rem;
    border-top:1px solid var(--line);padding-top:22px}
  footer .copy{color:var(--ink);font-weight:600}

  @media (prefers-reduced-motion: reduce){
    *{transition:none !important;animation:none !important}
    html{scroll-behavior:auto}
  }
</style>
</head>
<body>
<div class="wrap">

  <header class="hero">
    <div class="globe" aria-hidden="true"></div>
    <h1>طبقات الأرض</h1>
    <div class="sub">رحلة إلى أعماق الكوكب: القشرة، والوشاح، واللب</div>
    <span class="tag">عرض بصري تفاعلي · بدون أي موارد خارجية</span>
  </header>

  <h2 class="section"><span class="dot"></span> مقطع توضيحي داخلي للأرض</h2>
  <p style="color:var(--ink-soft);margin:-6px 4px 18px">
    اضغط على أي طبقة في الرسم أو في القائمة لتستكشف خصائصها.
    (الرسم توضيحي وغير مُقَيَّد بالمقياس الحقيقي؛ فالقشرة رقيقة جدًا مقارنةً بباقي الطبقات.)
  </p>

  <section class="stage">
    <div class="earth-box">
      <div class="earth" id="earth" data-active="mantle" role="img"
           aria-label="مقطع دائري يوضح طبقات الأرض: قشرة ثم وشاح ثم لب خارجي ثم لب داخلي">
        <div class="ring crust" data-layer="crust"  tabindex="0" role="button" aria-label="القشرة"></div>
        <div class="ring mantle" data-layer="mantle" tabindex="0" role="button" aria-label="الوشاح"></div>
        <div class="ring outer"  data-layer="outer"  tabindex="0" role="button" aria-label="اللب الخارجي"></div>
        <div class="ring inner"  data-layer="inner"  tabindex="0" role="button" aria-label="اللب الداخلي"></div>
      </div>

      <div class="legend" id="legend" role="group" aria-label="قائمة الطبقات">
        <button class="chip" data-layer="crust" aria-pressed="false"><span class="sw crust"></span> القشرة الأرضية <small>Crust</small></button>
        <button class="chip" data-layer="mantle" aria-pressed="true"><span class="sw mantle"></span> الوشاح <small>Mantle</small></button>
        <button class="chip" data-layer="outer" aria-pressed="false"><span class="sw outer"></span> اللب الخارجي <small>Outer core</small></button>
        <button class="chip" data-layer="inner" aria-pressed="false"><span class="sw inner"></span> اللب الداخلي <small>Inner core</small></button>
      </div>
    </div>

    <div class="info" id="info" aria-live="polite">
      <!-- filled by JS -->
    </div>
  </section>

  <h2 class="section"><span class="dot"></span> شرائح العمق من السطح إلى المركز</h2>
  <div class="scale" aria-hidden="false">
    <div class="band crust">القشرة الأرضية <span class="t">0 – 70 كم · صلبة</span></div>
    <div class="band mantle">الوشاح <span class="t">7 – 2890 كم · لزج يتدفق</span></div>
    <div class="band outer">اللب الخارجي <span class="t">2890 – 5150 كم · سائل</span></div>
    <div class="band inner">اللب الداخلي <span class="t">5150 – 6371 كم · صلب</span></div>
  </div>

  <h2 class="section"><span class="dot"></span> بطاقات الطبقات التفصيلية</h2>
  <div class="cards">
    <article class="card crust">
      <h3>القشرة الأرضية</h3>
      <p class="depth">أرقّ الطبقات الخارجية الصلبة</p>
      <dl>
        <dt>السماكة</dt><dd>~5 كم محيطية، ~30–70 كم قارية</dd>
        <dt>التركيب</dt><dd>سيليكات: أكسجين، سيليكون، ألومنيوم، حديد، كالسيوم</dd>
        <dt>الحالة</dt><dd>صلبة وهشة</dd>
        <dt>الحرارة</dt><dd>من حرارة السطح حتى ~500–1000°م</dd>
      </dl>
    </article>

    <article class="card mantle">
      <h3>الوشاح</h3>
      <p class="depth">السماكة الكبرى والحرّك المُحرِّك للصفائح</p>
      <dl>
        <dt>السماكة</dt><dd>~2890 كم</dd>
        <dt>التركيب</dt><dd>سيليكات غنية بالحديد والمغنيسيوم (أوليفين، بريدجمانيت)</dd>
        <dt>الحالة</dt><dd>صلبة لكنها لزجة تتدفق ببطء</dd>
        <dt>الحرارة</dt><dd>~500 – 4000°م</dd>
      </dl>
    </article>

    <article class="card outer">
      <h3>اللب الخارجي</h3>
      <p class="depth">معدن منصهر يولّد المجال المغناطيسي</p>
      <dl>
        <dt>العمق</dt><dd>2890 – 5150 كم</dd>
        <dt>التركيب</dt><dd>حديد ونيكل منصهران</dd>
        <dt>الحالة</dt><dd>سائل متحرك</dd>
        <dt>الحرارة</dt><dd>~4000 – 5000°م</dd>
      </dl>
    </article>

    <article class="card inner">
      <h3>اللب الداخلي</h3>
      <p class="depth">كرة حديدية صلبة عند المركز</p>
      <dl>
        <dt>نصف القطر</dt><dd>~1220 كم</dd>
        <dt>التركيب</dt><dd>سبيكة حديد ونيكل</dd>
        <dt>الحالة</dt><dd>صلبة بفعل الضغط الهائل</dd>
        <dt>الحرارة</dt><dd>~5000 – 5400°م</dd>
      </dl>
    </article>
  </div>

  <h2 class="section"><span class="dot"></span> أرقام وأخطاء شائعة</h2>
  <div class="facts-grid">
    <div class="fact"><div class="big">6371 كم</div><div class="lbl">نصف قطر الأرض المتوسط من السطح حتى المركز.</div></div>
    <div class="fact"><div class="big">≈ 1%</div><div class="lbl">القشرة رقيقة نسبيًا؛ نسبةً لحجم الأرض فهي كقشر التفاحة.</div></div>
    <div class="fact"><div class="big">5400°م</div><div class="lbl">حرارة اللب الداخلي قريبة من حرارة سطح الشمس (~5500°م).</div></div>
    <div class="fact"><div class="big">سائل ≠ صلب</div><div class="lbl">اللب الخارجي سائل أما الداخلي فصلب رغم حرارة أعلى — والسبب الضغط.</div></div>
  </div>

  <footer>
    <div>عرض تعليمي مبني بالكامل على HTML و CSS و JavaScript مضمّنة — بدون خطوط أو مكتبات أو صور خارجية.</div>
    <div class="copy">© 2026 — طبقات الأرض · القشرة والوشاح واللب</div>
  </footer>

</div>

<script>
  (function(){
    var DATA = {
      crust:  {name:"القشرة الأرضية", en:"Crust", lead:"الطبقة الصلبة الرقيقة التي نعيش عليها.",
        rows:[["السماكة","~5 كم (محيطية) حتى ~30–70 كم (قارية)"],
              ["التركيب","سيليكات غنية بالأكسجين والسيليكون والألومنيوم"],
              ["الحالة","صلبة وهشة (تتكوّن منها الصفائح التكتونية)"],
              ["الحرارة","من حرارة السطح حتى ~500–1000°م"]],
        heat:10},
      mantle: {name:"الوشاح", en:"Mantle", lead:"أضخم طبقات الأرض، مادتها صلبة لكنها لزجة تتدفق.",
        rows:[["السماكة","~2890 كم (من أسفل القشرة حتى اللب الخارجي)"],
              ["التركيب","سيليكات غنية بالحديد والمغنيسيوم (أوليفين وبريدجمانيت)"],
              ["الحالة","صلبة لزجة؛ الطبقة اللزجة العليا تُسمى الأثينوسفير"],
              ["الحرارة","~500 – 4000°م"]],
        heat:70},
      outer:  {name:"اللب الخارجي", en:"Outer core", lead:"طبقة من الحديد المنصهر المتحرك تولّد المجال المغناطيسي.",
        rows:[["العمق","2890 – 5150 كم"],
              ["التركيب","حديد ونيكل منصهران"],
              ["الحالة","سائل متحرك (تأثير الدينامو)"],
              ["الحرارة","~4000 – 5000°م"]],
        heat:85},
      inner:  {name:"اللب الداخلي", en:"Inner core", lead:"كرة حديدية صلبة عند قلب الأرض رغم الحرارة الهائلة.",
        rows:[["نصف القطر","~1220 كم (حتى المركز عند 6371 كم)"],
